class Solution {
  public long bowlSubarrays(int[] nums) {
    int n = nums.length;
    int[] stack = new int[n];
    int sp = 0;
    long pairs = 0;
    for (int j = 0; j < n; j++) {
      while (sp > 0 && nums[stack[sp - 1]] < nums[j]) {
        sp--;
        pairs++;
      }
      if (sp > 0) pairs++;
      stack[sp++] = j;
    }
    return pairs - (n - 1);
  }
}
